item.command:
/bin/bash -lc "python3 - <<'PY'
import urllib.request, hashlib, json
base='https://raw.githubusercontent.com/openmm/openmm/53770948682c40bd460b39830d4e0f0fd3a4b868/'
urls={'benchmark':base+'examples/benchmark.py','pdb':base+'examples/5dfr_solv-cube_equil.pdb','tag':'https://api.github.com/repos/openmm/openmm/git/ref/tags/8.2.0','openmm':'https://pypi.org/pypi/openmm/8.2.0/json','cuda':'https://pypi.org/pypi/OpenMM-CUDA-12/8.2.0/json','platform':'https://docs.openmm.org/8.2.0/userguide/library/04_platform_specifics.html'}
for key,url in urls.items():
 try:
  raw=urllib.request.urlopen(url, timeout=25).read()
  print(key, 'URL',url,'bytes',len(raw))
  if key=='pdb': print('sha256',hashlib.sha256(raw).hexdigest(),'atom_records',sum(line.startswith((b'ATOM  ',b'HETATM')) for line in raw.splitlines()))
  elif key=='tag': print(raw.decode())
  elif key in ('openmm','cuda'):
   d=json.loads(raw);print(json.dumps({'requires_python':d['info']['requires_python'],'requires_dist':d['info']['requires_dist'],'licence':d['info']['license'],'linux_files':[{'filename':x['filename'],'sha256':x['digests']['sha256'],'size':x['size']} for x in d['urls'] if 'manylinux' in x['filename']]}))
  elif key=='benchmark':
   lines=raw.decode().splitlines()
   for i,line in enumerate(lines):
    if any(x in line for x in ['5dfr','amber99sb','tip3p','LangevinMiddle','hydrogenMass','ConstraintTolerance','cutoff','seconds','--test','--platform']): print(i+1,line)
  else:
   s=raw.decode();p=s.find('DeterministicForces');print(s[p:p+1500])
 except Exception as e: print(key,type(e).__name__,str(e))
PY"

